import os
import sys


def validate_file(path: str) -> None:
    """Check if the file exists and is not empty. Exit non-zero if invalid."""
    if not os.path.exists(path):
        sys.stderr.write(f"Error: File '{path}' does not exist.\n")
        sys.exit(1)
    if os.path.getsize(path) == 0:
        sys.stderr.write(f"Error: File '{path}' is empty.\n")
        sys.exit(1)
